// Carrot Revolt Labs · Flux Lab · stages, steps and live checklists.
// It runs on the ComfyUI Lab interface (../comfyui/app.js) and adds the Flux nodes and simulator (./nodes.js).
import { defaultGraph, makeNode, makeLink, connect } from '../comfyui/engine.js';
import { historyExtra as hx, VRAM, KONTEXT_PHOTO } from './nodes.js';
export const L = (en, ca, es) => ({ en, ca, es });

export const META = { key: 'carrot-revolt-comfy-flux:', title: 'Flux Lab', label: 'GENERATIVE IMAGE / COMFYUI · 04' };
export const historyExtra = hx;

/* ── Graph helpers ── */
const N = (g, type) => g.nodes.filter(n => n.type === type && n.mode === 0);
const into = (g, id, input) => g.links.find(l => l.to === id && l.input === input);
const from = (g, id, input) => { const l = into(g, id, input); return l ? g.nodes.find(n => n.id === l.from) : null; };
// Follow a conditioning wire back towards the prompt and list the node types it goes through.
const condPath = (g, id, input) => { const out = []; let n = from(g, id, input); for (let i = 0; n && i < 12; i++) { out.push(n); const next = ['conditioning', 'positive'].map(k => from(g, n.id, k)).find(Boolean); n = next; } return out; };
const goal = (text, test, optional = false) => ({ text, test, optional });
const add = (g, ...nodes) => { g.nodes.push(...nodes); return g; };
const wire = (g, list) => { for (const l of list) connect(g, makeLink(...l)); return g; };
const set = (g, id, k, v) => { g.nodes.find(n => n.id === id).widgets[k] = v; return g; };
const move = (g, id, x, y) => { const n = g.nodes.find(n => n.id === id); n.x = x; n.y = y; return g; };
const drop = (g, id) => { g.nodes = g.nodes.filter(n => n.id !== id); g.links = g.links.filter(l => l.from !== id && l.to !== id); return g; };
const runs = c => c.history.filter(h => h.family);
const ran = (c, f) => runs(c).some(f);
const flux = h => h.family === 'flux';
const PROMPT = 'a cat sitting in a sunny landscape, golden light, detailed';
const CAT_MASK = [.49, .58, .67, .76, .84].map(y => ({ p: [[.35, y], [.68, y]], r: .06 }));

/* ── Starters and solutions ── */
const G = {
  sd: (text = PROMPT, ckpt = 'dreamshaper_8.safetensors', size = 512) => { const g = defaultGraph(); set(g, 'pos', 'text', text); set(g, 'neg', 'text', 'blurry, text, watermark'); set(g, 'sampler', 'control_after_generate', 'fixed'); set(g, 'ckpt', 'ckpt_name', ckpt); set(g, 'latent', 'width', size); set(g, 'latent', 'height', size); return g; },
  flux: ({ unet = 'flux1-dev.safetensors', dtype = 'fp8_e4m3fn', gguf = null, type = 'flux', vae = 'ae.safetensors', cfg = 1, steps = 20, text = PROMPT, neg = '', fg = true, guidance = 3.5, w = 1024, h = 1024 } = {}) => {
    const g = drop(drop(defaultGraph(), 'ckpt'), 'latent');
    add(g, gguf ? makeNode('UnetLoaderGGUF', 26, 120, { unet_name: gguf }, 'unet') : makeNode('UNETLoader', 26, 120, { unet_name: unet, weight_dtype: dtype }, 'unet'), makeNode('DualCLIPLoader', 26, 300, { type }, 'clip'), makeNode('VAELoader', 26, 540, { vae_name: vae }, 'vae'), makeNode('EmptySD3LatentImage', 473, 609, { width: w, height: h }, 'latent'));
    set(g, 'pos', 'text', text); set(g, 'neg', 'text', neg);
    for (const [k, v] of Object.entries({ cfg, steps, sampler_name: 'euler', scheduler: 'simple', control_after_generate: 'fixed' })) set(g, 'sampler', k, v);
    wire(g, [['unet', 0, 'sampler', 'model'], ['clip', 0, 'pos', 'clip'], ['clip', 0, 'neg', 'clip'], ['vae', 0, 'decode', 'vae'], ['latent', 0, 'sampler', 'latent_image']]);
    if (fg) { add(g, makeNode('FluxGuidance', 863, 30, { guidance }, 'fg')); wire(g, [['pos', 0, 'fg', 'conditioning'], ['fg', 0, 'sampler', 'positive']]); }
    return g;
  },
  fill: (unet = 'flux1-fill-dev.safetensors', guidance = 30) => {
    const g = drop(G.flux({ unet, guidance, text: 'a blue robot in a landscape, detailed' }), 'latent');
    add(g, makeNode('LoadImage', 26, 760, { image: 'garden_cat.png', mask: CAT_MASK }, 'img'), makeNode('InpaintModelConditioning', 470, 640, {}, 'imc'));
    move(g, 'sampler', 1240, 186); move(g, 'decode', 1600, 188); move(g, 'save', 1850, 189); move(g, 'fg', 900, 30);
    return wire(g, [['fg', 0, 'imc', 'positive'], ['neg', 0, 'imc', 'negative'], ['vae', 0, 'imc', 'vae'], ['img', 0, 'imc', 'pixels'], ['img', 1, 'imc', 'mask'], ['imc', 0, 'sampler', 'positive'], ['imc', 1, 'sampler', 'negative'], ['imc', 2, 'sampler', 'latent_image']]);
  },
  kontext: (ref = true, text = 'make the cat black and turn the scene into night') => {
    const g = G.flux({ unet: 'flux1-kontext-dev.safetensors', guidance: 2.5, text });
    add(g, makeNode('LoadImage', 26, 760, { image: KONTEXT_PHOTO.name }, 'kimg'), makeNode('FluxKontextImageScale', 400, 860, {}, 'kscale'), makeNode('VAEEncode', 680, 860, {}, 'kenc'));
    wire(g, [['kimg', 0, 'kscale', 'image'], ['kscale', 0, 'kenc', 'pixels'], ['vae', 0, 'kenc', 'vae']]);
    if (ref) { add(g, makeNode('ReferenceLatent', 863, -90, {}, 'ref')); wire(g, [['pos', 0, 'ref', 'conditioning'], ['kenc', 0, 'ref', 'latent'], ['ref', 0, 'fg', 'conditioning']]); }
    return g;
  },
  lora: (name = 'watercolor_sd15.safetensors', text = PROMPT) => { const g = G.flux({ text }); add(g, makeNode('LoraLoaderModelOnly', 400, 20, { lora_name: name }, 'lora')); return wire(g, [['unet', 0, 'lora', 'model'], ['lora', 0, 'sampler', 'model']]); },
};

