        how: [L('Run with flux1-dev: the border shows.', 'Executa amb flux1-dev: es veu la vora.', 'Ejecuta con flux1-dev: se ve el borde.'), L('Load Diffusion Model › <b>flux1-fill-dev</b>, run: guidance 3.5 is too low.', 'Load Diffusion Model › <b>flux1-fill-dev</b>, executa: guidance 3.5 és massa baixa.', 'Load Diffusion Model › <b>flux1-fill-dev</b>, ejecuta: guidance 3.5 es demasiado baja.'), L('FluxGuidance › <b>30</b>. Run.', 'FluxGuidance › <b>30</b>. Executa.', 'FluxGuidance › <b>30</b>. Ejecuta.')],
